    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 14-year-old male presents with deep, aching pain in the posterior spine that is characteristically worse at night. The pain is completely relieved by ibuprofen. Radiographs show a small (< 1.5 cm) radiolucent nidus surrounded by dense reactive sclerosis. What is the most appropriate definitive management if symptoms become refractory?', '["Intravenous bisphosphonates", "Radiation therapy", "Radiofrequency ablation (RFA)", "Curettage and bone grafting", "Chemotherapy followed by limb-salvage surgery"]'::jsonb, 2, 'Osteoid osteoma classically presents with night pain relieved by NSAIDs due to high prostaglandin (PGE2) production by the tumor nidus. CT is the best imaging modality to visualize the nidus. If medical management fails or is poorly tolerated, percutaneous radiofrequency ablation (RFA) is the treatment of choice.'),
    (v_topic_id, 'A 79-year-old male presents with severe back pain. Radiographs of the lumbar spine show a dense, sclerotic (osteoblastic) lesion in the L3 vertebral body. Laboratory studies show an elevated alkaline phosphatase, but normal calcium. Which primary malignancy is most likely responsible for this metastatic lesion?', '["Prostate carcinoma", "Renal cell carcinoma", "Multiple myeloma", "Thyroid carcinoma", "Malignant melanoma"]'::jsonb, 0, 'Metastatic prostate cancer characteristically produces osteoblastic (sclerotic) bone lesions due to the secretion of factors that stimulate bone formation (like BMPs). Conversely, cancers like renal cell, thyroid, and multiple myeloma typically cause osteolytic (destructive) lesions.'),
    (v_topic_id, 'A 21-year-old patient presents with rapid swelling of the humerus. Radiographs show an eccentric, expansile metaphyseal lesion. MRI shows multiple fluid-fluid levels. What does this MRI finding represent?', '["Contrast pooling in a hemangioma", "Fat floating on water within a lipoma", "Necrotic tumor debris", "Pus settling from an abscess", "Separation of cellular blood components from serum"]'::jsonb, 4, 'The ''''fluid-fluid level'''' on MRI in an aneurysmal bone cyst (ABC) represents the settling of red blood cells out of serum in the cyst''''s cavernous, blood-filled spaces.'),
    (v_topic_id, 'A 83-year-old patient presents with back pain and fatigue. Radiographs of the skull and spine show multiple ''punched-out'' radiolucencies without any surrounding reactive sclerosis. Laboratory tests reveal hypercalcemia, anemia, and an M-spike on serum protein electrophoresis. Which bone scan finding is expected?', '["Increased uptake exclusively in the appendicular skeleton", "A falsely negative (''cold'' or normal) bone scan", "Diffuse periosteal uptake", "Intensely increased uptake (''hot'' spots) in all lesions", "A ''superscan'' with absent renal visualization"]'::jsonb, 1, 'Multiple myeloma lesions are purely osteolytic, caused by myeloma cells stimulating osteoclasts (via RANKL) and actively inhibiting osteoblasts (via DKK-1). Because a Technetium-99m bone scan relies on osteoblastic activity (bone formation), it is notoriously unreliable (falsely negative) in multiple myeloma. A skeletal survey (plain films) or low-dose whole-body CT is the preferred imaging modality.'),
    (v_topic_id, 'A 51-year-old female with a history of breast cancer presents with a pathologic fracture of the proximal radius. The lesion is lytic. What is the primary goal of orthopedic stabilization in this setting?', '["Delaying surgery until radiation therapy is completed", "Achieving a biologic union of the fracture site without cement", "Immediate pain relief, early mobilization, and restoration of function", "Preventing pulmonary metastasis", "Curative resection of the tumor with wide margins"]'::jsonb, 2, 'The treatment of metastatic pathologic fractures is generally palliative. The goals are to provide immediate mechanical stability (often using intramedullary nails and cement), relieve pain, and allow early weight-bearing and functional independence.'),
    (v_topic_id, 'A 14-year-old male presents with deep, aching pain in the proximal femur that is characteristically worse at night. The pain is completely relieved by ibuprofen. Radiographs show a small (< 1.5 cm) radiolucent nidus surrounded by dense reactive sclerosis. What is the most appropriate definitive management if symptoms become refractory?', '["Curettage and bone grafting", "Radiofrequency ablation (RFA)", "Wide surgical resection", "Radiation therapy", "Chemotherapy followed by limb-salvage surgery"]'::jsonb, 1, 'Osteoid osteoma classically presents with night pain relieved by NSAIDs due to high prostaglandin (PGE2) production by the tumor nidus. CT is the best imaging modality to visualize the nidus. If medical management fails or is poorly tolerated, percutaneous radiofrequency ablation (RFA) is the treatment of choice.'),
    (v_topic_id, 'A 7-year-old patient has intense nocturnal pain in the radius that responds dramatically to naproxen. Imaging confirms a nidus with surrounding sclerosis. If the patient opts for minimally invasive intervention, what is the treatment of choice?', '["Cryoablation without imaging", "Intra-articular steroid injection", "CT-guided radiofrequency ablation (RFA)", "Open en bloc resection", "Radiation therapy"]'::jsonb, 2, 'Osteoid osteomas are benign bone-forming tumors. While they can ''''burn out'''' spontaneously over years, symptomatic patients who cannot tolerate long-term NSAIDs are best treated with percutaneous, CT-guided radiofrequency ablation, which has a very high success rate.'),
    (v_topic_id, 'A 17-year-old patient is diagnosed with high-grade conventional osteosarcoma of the distal pelvis. They are scheduled for a limb-salvage procedure. According to standard protocol, what must precede the surgical resection?', '["Bisphosphonates", "Amputation", "Neoadjuvant chemotherapy", "Denosumab", "Radiation therapy"]'::jsonb, 2, 'Standard treatment for high-grade osteosarcoma includes neoadjuvant (preoperative) chemotherapy, which targets micrometastases and shrinks the tumor, followed by wide surgical resection and adjuvant chemotherapy.'),
    (v_topic_id, 'A 14-year-old patient presents with rapid swelling of the tibia. Radiographs show an eccentric, expansile metaphyseal lesion. MRI shows multiple fluid-fluid levels. What does this MRI finding represent?', '["Pus settling from an abscess", "Separation of cellular blood components from serum", "Contrast pooling in a hemangioma", "Fat floating on water within a lipoma", "Necrotic tumor debris"]'::jsonb, 1, 'The ''''fluid-fluid level'''' on MRI in an aneurysmal bone cyst (ABC) represents the settling of red blood cells out of serum in the cyst''''s cavernous, blood-filled spaces.'),
    (v_topic_id, 'A 37-year-old patient presents with knee pain. Radiographs reveal an eccentric, expansile, lytic lesion resembling a ''soap bubble'' in the epiphysis of the distal femur extending to the subchondral bone. Biopsy shows mononuclear cells and numerous multinucleated giant cells. Which targeted systemic therapy can be used as an adjunct for large, unresectable, or recurrent lesions?', '["Infliximab (TNF-alpha inhibitor)", "Denosumab (RANKL inhibitor)", "Rituximab (Anti-CD20)", "Methotrexate", "Imatinib (Tyrosine kinase inhibitor)"]'::jsonb, 1, 'Giant Cell Tumor of bone classically occurs in skeletally mature individuals (epiphysis/metaphysis). The neoplastic mononuclear stromal cells express RANKL, which recruits and activates the multinucleated osteoclast-like giant cells. Denosumab, a monoclonal antibody against RANKL, is an effective targeted therapy.'),
    (v_topic_id, 'A 44-year-old patient requires an open incisional biopsy for a suspected high-grade soft tissue sarcoma of the anterior thigh. Which of the following is a critical principle when performing this biopsy?', '["Obtain a small sample of the necrotic center rather than the periphery to ensure a diagnosis", "Dissect extensively through intermuscular planes to avoid muscle damage", "Use a longitudinal incision placed within the planned definitive resection ellipse", "Exsanguinate the limb with an Esmarch bandage before inflating the tourniquet", "Use a transverse incision parallel to skin tension lines for a better cosmetic result"]'::jsonb, 2, 'Orthopedic oncology biopsy principles: 1) Longitudinal incisions (transverse incisions contaminate more tissue longitudinally). 2) The biopsy tract must be excisable en bloc with the tumor. 3) Avoid spreading through fascial planes (split muscle instead). 4) Do NOT exsanguinate with an Esmarch to prevent pushing tumor cells centrally. 5) Biopsy the periphery (the advancing edge), as the center is often necrotic.'),
    (v_topic_id, 'A 67-year-old female with a history of breast cancer presents with a pathologic fracture of the proximal femur. The lesion is lytic. What is the primary goal of orthopedic stabilization in this setting?', '["Preventing pulmonary metastasis", "Immediate pain relief, early mobilization, and restoration of function", "Delaying surgery until radiation therapy is completed", "Curative resection of the tumor with wide margins", "Achieving a biologic union of the fracture site without cement"]'::jsonb, 1, 'The treatment of metastatic pathologic fractures is generally palliative. The goals are to provide immediate mechanical stability (often using intramedullary nails and cement), relieve pain, and allow early weight-bearing and functional independence.'),
    (v_topic_id, 'A 13-year-old patient presents with chronic, dull knee pain. Radiographs reveal a well-demarcated, small lytic lesion exclusively located within the epiphysis of the proximal tibia. Biopsy shows ''chicken-wire'' calcifications and mononuclear cells. What is the most likely diagnosis?', '["Giant Cell Tumor", "Enchondroma", "Osteosarcoma", "Chondroblastoma", "Chondromyxoid fibroma"]'::jsonb, 3, 'Chondroblastoma is a rare, benign cartilage-forming tumor that characteristically occurs in the epiphysis (or apophysis) of long bones in skeletally immature patients (unlike Giant Cell Tumors, which usually occur after physeal closure). Histology classically shows ''''chicken-wire'''' calcifications.'),
    (v_topic_id, 'A 78-year-old male presents with severe back pain. Radiographs of the lumbar spine show a dense, sclerotic (osteoblastic) lesion in the L3 vertebral body. Laboratory studies show an elevated alkaline phosphatase, but normal calcium. Which primary malignancy is most likely responsible for this metastatic lesion?', '["Renal cell carcinoma", "Thyroid carcinoma", "Multiple myeloma", "Malignant melanoma", "Prostate carcinoma"]'::jsonb, 4, 'Metastatic prostate cancer characteristically produces osteoblastic (sclerotic) bone lesions due to the secretion of factors that stimulate bone formation (like BMPs). Conversely, cancers like renal cell, thyroid, and multiple myeloma typically cause osteolytic (destructive) lesions.'),
    (v_topic_id, 'A 62-year-old patient presents with a slowly worsening ache in the proximal femur. Radiographs show a large, poorly defined intramedullary lesion with endosteal scalloping and prominent ''popcorn'' or ''ring-and-arc'' calcifications. Biopsy confirms malignant cartilage. What is the primary modality of treatment?', '["Denosumab therapy", "Systemic chemotherapy", "Radiofrequency ablation", "Wide surgical resection", "High-dose radiation therapy"]'::jsonb, 3, 'Chondrosarcomas are malignant tumors of cartilage typically seen in older adults (pelvis, proximal femur). They are notoriously resistant to both chemotherapy and radiation therapy. Therefore, wide surgical excision is the mainstay of treatment for conventional chondrosarcomas.'),
    (v_topic_id, 'A 75-year-old male presents with severe back pain. Radiographs of the lumbar spine show a dense, sclerotic (osteoblastic) lesion in the L3 vertebral body. Laboratory studies show an elevated alkaline phosphatase, but normal calcium. Which primary malignancy is most likely responsible for this metastatic lesion?', '["Renal cell carcinoma", "Multiple myeloma", "Thyroid carcinoma", "Prostate carcinoma", "Malignant melanoma"]'::jsonb, 3, 'Metastatic prostate cancer characteristically produces osteoblastic (sclerotic) bone lesions due to the secretion of factors that stimulate bone formation (like BMPs). Conversely, cancers like renal cell, thyroid, and multiple myeloma typically cause osteolytic (destructive) lesions.'),
    (v_topic_id, 'A 50-year-old patient requires an open incisional biopsy for a suspected high-grade soft tissue sarcoma of the anterior thigh. Which of the following is a critical principle when performing this biopsy?', '["Use a longitudinal incision placed within the planned definitive resection ellipse", "Dissect extensively through intermuscular planes to avoid muscle damage", "Obtain a small sample of the necrotic center rather than the periphery to ensure a diagnosis", "Use a transverse incision parallel to skin tension lines for a better cosmetic result", "Exsanguinate the limb with an Esmarch bandage before inflating the tourniquet"]'::jsonb, 0, 'Orthopedic oncology biopsy principles: 1) Longitudinal incisions (transverse incisions contaminate more tissue longitudinally). 2) The biopsy tract must be excisable en bloc with the tumor. 3) Avoid spreading through fascial planes (split muscle instead). 4) Do NOT exsanguinate with an Esmarch to prevent pushing tumor cells centrally. 5) Biopsy the periphery (the advancing edge), as the center is often necrotic.'),
    (v_topic_id, 'A 85-year-old female with a history of breast cancer presents with a pathologic fracture of the proximal femur. The lesion is lytic. What is the primary goal of orthopedic stabilization in this setting?', '["Curative resection of the tumor with wide margins", "Immediate pain relief, early mobilization, and restoration of function", "Achieving a biologic union of the fracture site without cement", "Preventing pulmonary metastasis", "Delaying surgery until radiation therapy is completed"]'::jsonb, 1, 'The treatment of metastatic pathologic fractures is generally palliative. The goals are to provide immediate mechanical stability (often using intramedullary nails and cement), relieve pain, and allow early weight-bearing and functional independence.'),
    (v_topic_id, 'A 73-year-old female with a history of breast cancer presents with a pathologic fracture of the proximal pelvis. The lesion is lytic. What is the primary goal of orthopedic stabilization in this setting?', '["Achieving a biologic union of the fracture site without cement", "Preventing pulmonary metastasis", "Delaying surgery until radiation therapy is completed", "Curative resection of the tumor with wide margins", "Immediate pain relief, early mobilization, and restoration of function"]'::jsonb, 4, 'The treatment of metastatic pathologic fractures is generally palliative. The goals are to provide immediate mechanical stability (often using intramedullary nails and cement), relieve pain, and allow early weight-bearing and functional independence.'),
    (v_topic_id, 'A 65-year-old patient presents with back pain and fatigue. Radiographs of the skull and spine show multiple ''punched-out'' radiolucencies without any surrounding reactive sclerosis. Laboratory tests reveal hypercalcemia, anemia, and an M-spike on serum protein electrophoresis. Which bone scan finding is expected?', '["Intensely increased uptake (''hot'' spots) in all lesions", "Diffuse periosteal uptake", "A ''superscan'' with absent renal visualization", "A falsely negative (''cold'' or normal) bone scan", "Increased uptake exclusively in the appendicular skeleton"]'::jsonb, 3, 'Multiple myeloma lesions are purely osteolytic, caused by myeloma cells stimulating osteoclasts (via RANKL) and actively inhibiting osteoblasts (via DKK-1). Because a Technetium-99m bone scan relies on osteoblastic activity (bone formation), it is notoriously unreliable (falsely negative) in multiple myeloma. A skeletal survey (plain films) or low-dose whole-body CT is the preferred imaging modality.'),
